/*
 Problem: 940. Distinct Subsequences II
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 8.9 MB (53.06%)
 Tags: String, Dynamic Programming
*/
class Solution {
public:
    int distinctSubseqII(string s) {
        const int MOD = 1e9 + 7;
        long long dp = 1, last[26]{};

        for (const auto& c : s) {
            long long ndp = 2 * dp - last[c - 'a'];
            last[c - 'a'] = dp;
            dp = (ndp + MOD) % MOD;
        }

        return (dp - 1 + MOD) % MOD;
    }
};
